#include "berti.h"

#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <iostream>

#include "cache.h"

 // EVOLVE-BLOCK-START
namespace {
  // Timeliness classification: ratio of access latency to avg miss latency
  // Make "timely" stricter and detect "late" earlier to reduce pollution from
  // chronically late prefetches. Stricter timely avoids issuing prefetches
  // that arrive just-in-time (which can increase memory traffic without benefit).
  constexpr double TIMELY_THRESHOLD = 0.30;  // below this → timely prefetch (stricter)
  constexpr double LATE_THRESHOLD   = 1.10;  // above this → late prefetch (earlier classification)

  // Weights in composite_score()
  // Reduce raw coverage weight (diminishing returns) and prioritize timeliness
  // and penalize late outcomes strongly.
  constexpr double COVERAGE_WEIGHT    = 0.6;
  constexpr double TIMELINESS_WEIGHT  = 3.0;
  constexpr double ACCURACY_WEIGHT    = 4.0;

  // How many deltas to prefetch per access
  // Reduce degree to limit bandwidth and pollution; multi-step prefetching only
  // when we're confident about the stride.
  constexpr int PREFETCH_DEGREE = 2;

  // Per-PC history buffer depth (capped at pc_entry::history array size = 16)
  // Shorter history focuses on recent behavior and reduces stale noise.
  constexpr int HISTORY_DEPTH = 10;

  // Minimum observations of a delta before trusting it
  // Raise threshold to avoid acting on very noisy deltas.
  constexpr int MIN_CONFIDENCE = 3;

  // Maximum absolute delta value to track
  // Concentrate on local deltas which are more likely to be stable.
  constexpr int MAX_DELTA = 24;

  // Throttle fill-level prefetches when MSHR is this full
  // Be conservative under contention to avoid flooding memory with fills.
  constexpr double MSHR_THRESHOLD = 0.35;
} // namespace

double berti::composite_score(int timely, int late, int total)
{
  // No observations → no score.
  if (total <= 0)
    return 0.0;

  // Convert to doubles for stable arithmetic.
  double t = static_cast<double>(timely);
  double l = static_cast<double>(late);
  double tot = static_cast<double>(total);

  // Fractions of outcomes.
  double timely_ratio = t / tot;
  double late_ratio = l / tot;

  // Coverage reward with diminishing returns (logarithmic).
  double coverage_score = std::log2(tot + 1.0);

  // Confidence mapping: smooth boost for well-observed deltas (range ~0.2..1.0)
  double confidence = std::min(1.0, (std::log2(tot + 1.0) / 5.0) + 0.2);

  // Consistency: timely minus late (positive is good)
  double consistency = timely_ratio - late_ratio;

  // Strong late penalty: linear + super-linear component to avoid deltas that
  // produce many late prefetches (cause pollution and wasted bandwidth).
  double late_penalty = late_ratio + 1.5 * (late_ratio * late_ratio);

  // Compose score:
  // - modest reward for coverage (diminishing) scaled by confidence
  // - reward consistency (timely vs late) amplified by confidence
  // - strong penalty for late outcomes
  double score = COVERAGE_WEIGHT * coverage_score * confidence
               + TIMELINESS_WEIGHT * consistency * confidence
               - ACCURACY_WEIGHT * late_penalty;

  // Small-count noise penalty: disfavour choices with very few observations.
  score -= 1.0 / (tot + 1.0);

  // Safety penalty: if timely fraction is very low, subtract extra to avoid
  // choosing deltas that rarely generate timely prefetches even if coverage is high.
  if (timely_ratio < 0.20)
    score -= (0.20 - timely_ratio) * 3.0;

  // Tiny tie-breaker: prefer slightly higher coverage when scores are almost equal.
  score += 1e-7 * coverage_score;

  return score;
}
// EVOLVE-BLOCK-END

void berti::add_history(pc_entry& entry, champsim::block_number block, uint64_t cycle)
{
  int depth = std::min(HISTORY_DEPTH, 16);
  entry.history[static_cast<std::size_t>(entry.history_head)] = {block, cycle};
  entry.history_head = (entry.history_head + 1) % depth;
  if (entry.history_size < depth)
    entry.history_size++;
}

int berti::best_delta(const pc_entry& entry)
{
  double best_score = -1.0;
  int best_d = 0;

  for (int d = -MAX_DELTA; d <= MAX_DELTA; d++) {
    if (d == 0)
      continue;
    auto idx = static_cast<std::size_t>(d + MAX_DELTA);
    const auto& ds = entry.deltas[idx];
    if (ds.count < MIN_CONFIDENCE)
      continue;
    double score = composite_score(ds.timely, ds.late, ds.count);
    if (score > best_score) {
      best_score = score;
      best_d = d;
    }
  }
  return best_d;
}

void berti::record_pending(champsim::block_number block, uint64_t cycle)
{
  std::size_t oldest_idx = 0;
  uint64_t oldest_cycle = UINT64_MAX;
  for (std::size_t i = 0; i < PENDING_SIZE; i++) {
    if (!pending[i].valid) {
      pending[i] = {block, cycle, true};
      return;
    }
    if (pending[i].issue_cycle < oldest_cycle) {
      oldest_cycle = pending[i].issue_cycle;
      oldest_idx = i;
    }
  }
  pending[oldest_idx] = {block, cycle, true};
}

void berti::prefetcher_initialize()
{
  current_cycle = 0;
  pending.fill({});
}

uint32_t berti::prefetcher_cache_operate(champsim::address addr, champsim::address ip, uint8_t cache_hit, bool useful_prefetch, access_type type,
                                         uint32_t metadata_in)
{
  champsim::block_number block{addr};

  auto found = pc_table.check_hit({ip});

  if (found.has_value()) {
    int depth = std::min(HISTORY_DEPTH, 16);
    for (int i = 0; i < found->history_size; i++) {
      auto& hist = found->history[static_cast<std::size_t>(i)];
      if (hist.timestamp == 0)
        continue;
      int64_t delta = champsim::offset(hist.block, block);
      if (delta == 0 || std::abs(delta) > MAX_DELTA)
        continue;

      auto idx = static_cast<std::size_t>(delta + MAX_DELTA);
      found->deltas[idx].count++;

      uint64_t latency = current_cycle - hist.timestamp;
      double avg_miss_latency = 200.0;
      double ratio = static_cast<double>(latency) / avg_miss_latency;
      if (ratio < TIMELY_THRESHOLD) {
        found->deltas[idx].timely++;
      } else if (ratio > LATE_THRESHOLD) {
        found->deltas[idx].late++;
      }
    }

    add_history(*found, block, current_cycle);

    int bd = best_delta(*found);

    pc_table.fill(*found);

    if (bd != 0) {
      for (int d = 1; d <= PREFETCH_DEGREE; d++) {
        champsim::address pf_addr{champsim::block_number{block + static_cast<int64_t>(bd) * d}};
        if (intern_->virtual_prefetch || champsim::page_number{pf_addr} == champsim::page_number{addr}) {
          bool fill_this = intern_->get_mshr_occupancy_ratio() < MSHR_THRESHOLD;
          bool success = prefetch_line(pf_addr, fill_this, metadata_in);
          if (success) {
            record_pending(champsim::block_number{pf_addr}, current_cycle);
          }
        }
      }
    }
  } else {
    pc_entry new_entry{};
    new_entry.ip = ip;
    add_history(new_entry, block, current_cycle);
    pc_table.fill(new_entry);
  }

  return metadata_in;
}

uint32_t berti::prefetcher_cache_fill(champsim::address addr, long set, long way, uint8_t prefetch, champsim::address evicted_addr, uint32_t metadata_in)
{
  if (prefetch) {
    champsim::block_number block{addr};
    for (auto& p : pending) {
      if (p.valid && p.block == block) {
        p.valid = false;
        break;
      }
    }
  }
  return metadata_in;
}

void berti::prefetcher_cycle_operate()
{
  current_cycle++;
}

void berti::prefetcher_final_stats()
{
  std::cout << "Berti evolvable params: TIMELY_THR=" << TIMELY_THRESHOLD << " LATE_THR=" << LATE_THRESHOLD << " COV_W=" << COVERAGE_WEIGHT
            << " TIME_W=" << TIMELINESS_WEIGHT << " ACC_W=" << ACCURACY_WEIGHT << " PF_DEGREE=" << PREFETCH_DEGREE << " HIST_DEPTH=" << HISTORY_DEPTH
            << " MIN_CONF=" << MIN_CONFIDENCE << std::endl;
}

